$string['settings:embed_dimensions'] = '嵌入维度';
$string['settings:embed_dimensions_desc'] = '嵌入向量的维度，必须是该模型确实提供的维度。OpenAI text-embedding-3-small：1536。nomic-embed-text：768。Voyage 模型接受 256、512、1024 和 2048（原生的 1024 会从请求中省略）；不合法的维度会被省略而不是发送出去，否则你会不知不觉地拿到原生维度而不是你要求的维度。voyage-4-large 配 2048 是实测过的配置——在真实查询上召回率提高 14.0 个百分点，每月不到 $4——采用它需要「完整重建索引」，因为检索器拒绝把查询与来自另一个嵌入空间的 chunk 打分。请使用 RAG 索引页面上的嵌入模型迁移功能，而不要先改这个值。';
