// v4.4.0: course-page CSP setting.
$string['settings:csp_course_pages_mode'] = '课程页面内容安全策略（CSP）';
$string['settings:csp_course_pages_mode_desc'] = '在 AI 课程助手小部件生效的课程页面上可选发送 CSP 响应头。<strong>关闭</strong>：不发送响应头（默认）。<strong>仅报告</strong>：发送 <code>Content-Security-Policy-Report-Only</code> — 浏览器记录违规但不拦截，适合做一周的观察期。<strong>强制</strong>：发送 <code>Content-Security-Policy</code> — 浏览器会拦截白名单之外的 iframe 源、fetch 请求和其他有风险的加载。这有助于控制被粘贴进站点「额外的 HTML」配置中的任意脚本所造成的影响（2026-04-29 的 IBL AI / Raison 事件）。不影响 [[tutorshort]] 自身的端点，它们始终发送更严格的 CSP。';
$string['settings:csp_mode_off'] = '关闭（课程页面不发送响应头）';
$string['settings:csp_mode_report_only'] = '仅报告（记录违规，不拦截）';
$string['settings:csp_mode_enforce'] = '强制（拦截白名单之外的加载）';
// v4.5.0: site-wide pedagogy defaults.
$string['settings:pedagogy_defaults_heading'] = '教学法默认值';
$string['settings:pedagogy_defaults_heading_desc'] = '每项教学法功能的站点级默认状态。在此开启某项功能后，所有课程都会继承它，除非该课程在其 [[tutorshort]] 课程设置页面上设有显式覆盖（强制开启/强制关闭）。升级到 v4.5.0 时，所有取旧版「默认关闭」值 <code>0</code> 的课程级「强制关闭」覆盖都会被清除，使新的全局默认值干净地生效。默认关闭 — 在管理员开启某项功能之前，从 v4.4.x 升级不会带来任何变化。';
$string['pedagogy:mastery'] = '默认开启掌握度跟踪';
$string['pedagogy:mastery_desc'] = '开启后，除非课程自行覆盖此设置，否则所有课程都会继承掌握度跟踪。掌握度跟踪需要经过整理的学习目标；没有学习目标的课程会平稳降级，不会报错。';
$string['pedagogy:socratic_mode'] = '默认开启苏格拉底式模式';
$string['pedagogy:socratic_mode_desc'] = '开启后，除非课程自行覆盖此设置，否则 [[tutorshort]] 在所有课程中都会先提出问题，而不是直接给出答案。';
$string['pedagogy:worked_examples'] = '默认开启示例解题开场白';
$string['pedagogy:worked_examples_desc'] = '开启后，除非课程自行覆盖此设置，否则“给我看一个示例解题”对话开场白会出现在所有课程中。';
$string['pedagogy:flashcards'] = '默认开启记忆卡片';
