// v4.6.0: vendor DPA gating + override editors.
$string['settings:vendor_data_heading'] = '供应商与成本数据';
$string['settings:vendor_data_heading_desc'] = '用于可选的供应商 DPA 管理页面，以及让管理员无需改动代码即可保持内置供应商表和 LLM 费率表为最新的覆盖编辑器的相关控制项。两个覆盖编辑器都使用 JSON；留空则回退到插件随附的硬编码默认值。';
$string['settings:vendor_dpa_admin_page_enabled'] = '显示供应商 DPA 管理页面';
$string['settings:vendor_dpa_admin_page_enabled_desc'] = '开启后，「供应商 DPA 状态」会出现在 网站管理 → 插件 → 本地插件 → AI 课程助手 下。该页面会渲染与下方覆盖设置合并后的供应商表。默认关闭 — 大多数管理员不需要这个页面。';
$string['settings:vendor_dpa_overrides'] = '供应商 DPA 覆盖（JSON）';
$string['settings:vendor_dpa_overrides_desc'] = 'JSON object keyed by vendor id. Each value is an object whose fields override the hardcoded vendor row. Fields you do not specify fall through to the default. A new vendor key in the override is added to the table; edits apply per field. Malformed JSON is ignored at runtime — fix the parse error here when the saved value does not appear in the Vendor DPA page.';
$string['settings:rate_card_overrides'] = 'LLM 费率表覆盖（JSON）';
$string['settings:rate_card_overrides_desc'] = '以模型名称前缀为键的 JSON 对象。每个值为 <code>{"input": float, "output": float}</code>，单位是每 1,000,000 tokens 的美元数。它会替换该前缀在内置费率表中的条目。示例：<pre>{ "gpt-4o-mini": { "input": 0.15, "output": 0.60 }, "claude-sonnet-4.6": { "input": 3.00, "output": 15.00 } }</pre> 自 v7.4.0 起为只读：该字段仍会参与合并（优先于随代码发布的基线，低于模型注册表），以便已有的覆盖继续生效，但已不再有任何东西写入它，新价格应填在模型注册表中——那里会记录每个价格由谁设置以及设置时间。以前每周刷新会覆盖整个字段，在下一次运行时把手工填写的价格全部毁掉。';

// v4.7.0: rate-card auto-refresh.
$string['settings:rate_card_auto_refresh'] = '从上游自动刷新';
$string['settings:rate_card_auto_refresh_desc'] = '开启后，每周定时任务（服务器时间周一 02:30）会抓取下面的上游价格 JSON，将其转换为 [[tutorshort]] 的费率表结构，并逐行写入模型注册表。默认开启——关闭它可将费率表固定在上次抓取或手工填写的状态。管理员手工填写的价格绝不会被这次刷新覆盖，失败的运行则什么都不写；上次刷新状态显示在「Refresh now」按钮下方。';
