$string['settings:prompt_debug_enabled']      = 'Log assembled system prompt to file';
$string['settings:prompt_debug_enabled_desc'] = 'When on, every chat-turn writes the full assembled system prompt and per-section character counts to <code>moodledata/temp/sola_prompt_debug.log</code> (rolling at ~1MB). Default off. Use to measure prompt size empirically and audit which sections contribute the most tokens. The log contains the system prompt only (no learner input or PII).';
$string['settings:socratic_verbose'] = '详尽版苏格拉底模式提示词';
$string['settings:socratic_verbose_desc'] = '开启后，苏格拉底模式的课程会收到 v3.9.30 中最初加入的完整约 600 token 的「该做/不该做」指令。关闭时（默认），它们收到的是一行式指令，现代托管模型能可靠遵循，并且每轮节省约 600 token。如果某门课程运行在需要显式脚手架的较弱自托管模型上，请开启此项。';
$string['settings:prompt_budget_chars'] = '系统提示词字符预算';
$string['settings:prompt_budget_chars_desc'] = 'Maximum total size of the assembled system prompt before the user message, in characters. The structured prompt builder organises sections by category (identity, course context, learner state, behaviour, markers, safety) and drops or truncates the lowest-priority sections when the budget is exceeded. Safety guidance is always preserved in full. Default 8,000 characters (~2,000 tokens). Lower values reduce per-turn cost; higher values allow more course content to land in-prompt.';
$string['settings:current_page_content_maxchars'] = '当前页面内容上限（字符数）';
$string['settings:current_page_content_maxchars_desc'] = '当 RAG 关闭时，作为 "Current Page Content" 部分注入到系统提示中的当前页面文本的最大字符数。默认 8,000 能很好地为针对页面的问题提供依据，同时为结构和指令留出预算。（启用 RAG 后，页面改为由其自身最相关的片段提供依据，并偏向当前页面，因此此上限不适用。）非常长的页面会从头部截断至此字符数，因此极长页面的末尾可能不会被引用；启用 RAG 可避免这种情况。注重成本的站点可以调得更低（例如 3,000-4,000）。限定在 500-8,000 范围内。与 <code>prompt_budget_chars</code> 相互独立：此项仅限制页面部分；而预算限制整个提示。';
$string['settings:prompt_verbosity'] = '提示词详略程度';
$string['settings:prompt_verbosity_desc'] = '指令块（苏格拉底模式、外部资源）的默认详略程度。简洁（默认）是现代托管模型能可靠遵循的写法；标准会为中端模型补充显式的脚手架；详尽则保留 v3.9.30 时期为较弱的自托管模型准备的重量级指导。可通过 <code>prompt_verbosity_course_&lt;id&gt;</code> 按课程覆盖。';
$string['settings:prompt_verbosity_concise'] = '简洁（推荐用于托管模型）';
$string['settings:prompt_verbosity_standard'] = '标准';
$string['settings:prompt_verbosity_verbose'] = '详尽（用于较弱的自托管模型）';
$string['settings:prompt_metrics_enabled'] = '采集分区提示词指标';
$string['settings:prompt_metrics_enabled_desc'] = '开启时（默认），每轮聊天都会为组装出的提示词向 <code>moodledata/sola_prompt_metrics/YYYY-MM-DD.log</code> 写入一行 JSON，记录各类别的字符数。保留最近 7 天。指标管理页面会汇总这些数据，用于给出预算建议。不记录任何个人身份信息 — 只记录各分区的大小。如果贵机构完全不希望产生指标文件，请关闭此项。';
$string['settings:prompt_budget_auto_tune'] = '每日自动调整系统提示词预算（已弃用）';
$string['settings:prompt_budget_auto_tune_desc'] = '已弃用。除非上方的预算模式设为<strong>固定</strong>，否则本项不起作用。过去有一个每日任务，通过观察截断情况并追逐它见过的最大提示词来推断字符预算。由模型的上下文窗口推导预算做得更好：它不会来回摆动，也不需要预热数据。两者还会互相冲突，因为该任务会写入字符预算，而任何非默认值都会关闭推导出的预算。请保持关闭；将在未来版本中移除。建议值仍会显示在<a href="/local/ai_course_assistant/prompt_metrics.php">提示词指标</a>页面上。';
$string['task:auto_tune_prompt_budget'] = '根据观测到的指标自动调整 [[tutorshort]] 的提示预算';
