$string['task:milestone_check'] = '发送每日里程碑回顾邮件（v5.3.0）';
$string['task:struggle_signal_review'] = '将学习困难信号归入学生的私密记忆（v5.3.0）';
$string['empathy:title'] = '共情沟通与延续记忆（v5.3.0）';
$string['empathy:desc'] = '三项协同工作的功能，让 [[tutorshort]] 更像一位会倾听的教练。目标用于记录学习者为何而来。延续记忆会记住此前哪些内容较难，以便 [[tutorshort]] 换一个角度讲解。里程碑通过邮件庆祝连续学习记录和课程完成。每项功能都有独立的关闭开关，并需要学习者主动选择加入。困难信号绝不会离开聊天——绝不会就某次吃力的会话发送任何邮件。';
$string['empathy:outreach_master_enabled'] = '主动联系总开关';
$string['empathy:outreach_master_enabled_desc'] = '新安装的环境默认关闭。关闭时，无论下方各项功能开关如何设置，都绝不会发出任何一封共情邮件。请在检查过各项功能的默认值和每位学习者的同意流程之后，再开启此项。';
$string['empathy:goals_enabled'] = '启用职业目标对话';
$string['empathy:goals_enabled_desc'] = '让学习者自愿填写两个简短回答（为何来学、想成为什么），用于个性化。仅在聊天中使用；不发送邮件。可以放心保持开启。';
$string['empathy:milestones_enabled'] = '启用里程碑回顾邮件';
$string['empathy:milestones_enabled_desc'] = '当学习者达成连续 7 天、连续 30 天或完成课程时，发送一封简短温暖的邮件。需要开启上方的总开关，并取得每位学习者的同意。所有渠道合计，每位学习者每 7 天最多 1 封邮件，此为硬性上限。';
$string['empathy:memory_enabled'] = '启用延续个性化记忆';
$string['empathy:memory_enabled_desc'] = '让 [[tutorshort]] 跨会话保留关于学习者难点的少量私密笔记，以便下一次回复能换一个角度。有上限（每位学习者每门课程最多 5 条笔记，保留 90 天）。学习者可自行编辑。教师始终不可见。';
$string['empathy:struggle_enabled'] = '启用困难识别分类器';
$string['empathy:struggle_enabled_desc'] = '默认关闭。让 [[tutorshort]] 识别连续多轮对话中持续的挫败感，并在上方的延续记忆中悄悄记下一条卡点笔记。结果仅在聊天中使用；绝不会就吃力的会话发送任何邮件。信号数据在 7 天后自动清除。';
