$string['pedagogy:crossmastery'] = '默认开启跨课程掌握度汇总';
$string['pedagogy:crossmastery_desc'] = '开启后，[[tutorshort]] 会识别学习者是否已在其他课程中掌握某个目标（通过能力点引用或标题匹配），并认可其先前已具备的能力，而不再重复训练该目标。需启用掌握度追踪；未设置目标的课程将自动平稳回退。仅作为参考提示，不会更改学习者在任何课程中已存储的掌握度分数。';
