// Forward learning-path awareness (v5.8.0).
$string['pedagogy:program_path'] = '默认开启前向学习路径感知';
$string['pedagogy:program_path_desc'] = '开启后，[[tutorshort]] 可以告诉学习者当前课程在其项目（学位或证书）中接下来通向何处，以及今天的概念如何衔接到后续课程。该功能读取 Moodle Programs 插件（Degrees 和 Learn），仅在项目定义了先修要求或必修顺序时才指明具体的下一门课程；否则只说明学习者在路径中的位置。仅供参考——它绝不会更改注册或掌握度，且始终只使用当前学习者本人的项目分配。在不适用任何项目的情况下，它会静默地不执行任何操作。';

