$string['pedagogy:learning_path'] = '默认开启学习路径图和下一门课程提示';
$string['pedagogy:learning_path_desc'] = '开启后，[[tutorshort]] 会添加一个可视化的学习路径面板（小组件标题栏中的"我的路径"按钮），以课程序列的形式展示学员的学习项目，每门课程都可展开查看其目标以及学员的掌握情况。当学员达到当前课程的标准时（完成课程或掌握了较高比例的目标），[[tutorshort]] 还会温和地显示"已准备好学习下一门课程"的横幅，并在对话中提及。仅供建议参考；使用学员自己的学习项目分配；在不适用任何学习项目时静默不做任何操作。';
