$string['settings:active_learners_enabled'] = '显示活跃学习者指示条';
$string['settings:active_learners_enabled_desc'] = '在聊天面板中显示当前有多少其他人正在学习。这是一种社交激励而非教学功能，并且每个打开的面板每分钟都会向服务器轮询一次，因此默认关闭。仅当至少有另外两人活跃时才会显示。';

$string['task:unanswered_check'] = '[[tutorshort]] 未回答问题检查';
$string['settings:unanswered_check_enabled'] = '当问题无人回答时发出警报';
$string['settings:unanswered_check_enabled_desc'] = '当学习者向 [[tutorshort]] 提问却得不到回答时，向支出通知收件人发送邮件。成本异常检测器只在支出<em>上升</em>时触发；拒绝所有调用的服务商不产生费用，因此不会触发任何警报。此项监控提问与回答的比例，一旦服务商故障该比例即降为零。若通知列表为空，则使用站点管理员。';
$string['settings:unanswered_window_hours'] = '检查窗口（小时）';
$string['settings:unanswered_window_hours_desc'] = '每次运行回溯的时长。越短反应越快，但需要足够的流量才有意义。';
$string['settings:unanswered_min_questions'] = '发出警报所需的最少提问数';
$string['settings:unanswered_min_questions_desc'] = '课程需在窗口内达到此提问数才会被评估。低于此数时，少数学习者关闭标签页看起来就像故障。';
$string['settings:unanswered_min_answer_rate'] = '最低回答率';
$string['settings:unanswered_min_answer_rate_desc'] = '当获得回答的提问比例低于此值时发出警报。0.5 也能捕捉部分故障，而不仅是完全故障。设为 0 可停用此项检查。';

$string['settings:hidden_categories'] = '隐藏的课程分类';
$string['settings:hidden_categories_desc'] = '以逗号分隔的课程分类名称或 ID 列表，助手不会在这些分类下显示。例如："课程开发, 42"。开启编辑模式时，助手也会自动隐藏。';
$string['settings:provider_heading'] = 'AI 提供方与对话';
$string['settings:provider_heading_desc'] = '配置 AI 后端、模型以及对话行为。';
$string['settings:claude_temperature_allow_prefixes'] = '接受 temperature 参数的 Claude 模型';
$string['settings:claude_temperature_allow_prefixes_desc'] = '每行一个模型名称前缀。名称以其中任一前缀开头的 Anthropic 模型仍然接受 <code>temperature</code> 采样参数。任何与前缀不匹配的 Claude 模型都会省略 temperature（自 Opus 4.7 起的推理类模型会以 HTTP 400 拒绝该参数）。留空则使用随插件提供的默认值。';
$string['settings:max_tokens'] = '最大回复长度（令牌数）';
$string['settings:max_tokens_desc'] = '每次 AI 回复的最大令牌数。数值越低，回复越短、越快。512 约为 2-3 句话，1024 约为 1-2 段，2048 可容纳更长的解释。设为 0 表示不限制（使用提供方默认值）。';
$string['settings:profile_update_interval'] = '学生画像更新间隔';
$string['settings:profile_update_interval_desc'] = '当学生在某门课程中发送达到此数量的消息后，助手会生成（或刷新）一份学习画像，概括其优势、薄弱环节、学习风格和兴趣。该画像会被注入系统提示词，用于生成个性化回复。设为 0 可停用。默认值：10。';
$string['settings:enable_thinking'] = '扩展思考（仅限 Claude）';
$string['settings:enable_thinking_desc'] = '为 Claude 模型启用自适应思考。Claude 会自行决定在回答前何时思考以及思考多久。可提升复杂问题的准确性，但会增加令牌消耗和延迟。思考内容不会展示给学生。其他提供方会忽略此设置。';
$string['settings:rag_sources_heading'] = 'RAG 内容来源';
$string['settings:rag_sources_heading_desc'] = '选择 RAG 索引器从哪些课程内容类型中提取文本。<a href="{$a}">RAG 管理页面</a>上的状态指示会显示每个提取器是否具备运行所需的条件（例如 pdftotext 程序、Cloudflare 白名单）。';
$string['settings:rag_extract_pdf'] = '索引 PDF 文件（mod_resource）';
$string['settings:rag_extract_pdf_desc'] = '通过 <code>pdftotext</code> 程序（poppler）从上传的 PDF 中提取文本。会自动检测程序路径；如有需要可在下方手动指定。';
$string['settings:rag_pdftotext_path'] = 'pdftotext 程序路径';
$string['settings:rag_pdftotext_path_desc'] = '留空则自动检测（依次检查 <code>/usr/bin/pdftotext</code>、<code>/usr/local/bin/pdftotext</code> 以及 <code>which pdftotext</code>）。仅当您的安装位置不在上述路径时才需要填写。';
$string['settings:rag_extract_docx'] = '索引 DOCX 文件（mod_resource）';
$string['settings:rag_extract_docx_desc'] = '通过 PHP ZipArchive 从上传的 Word 文档中提取文本。无需任何外部依赖。';
$string['settings:rag_extract_pptx'] = '索引 PPTX 文件（mod_resource）';
$string['settings:rag_extract_pptx_desc'] = '通过 PHP ZipArchive 从上传的新版 PowerPoint 演示文稿中提取文本。按幻灯片顺序遍历幻灯片和演讲者备注的 XML；无需外部依赖。不支持旧版二进制 <code>.ppt</code> 文件——请将这些演示文稿另存为 <code>.pptx</code>。';
$string['settings:rag_extract_h5p'] = '索引 H5P 内容（mod_h5p）';
$string['settings:rag_extract_h5p_desc'] = '遍历 H5P 内容的 JSON，并索引其中所有包含文本的字段（问题、答案、反馈、描述）。H5P 内容类型的元数据较为宽泛；在个别边缘情况下可能出现误判。';
$string['settings:rag_extract_scorm'] = '索引 SCORM 课件包（mod_scorm）';
$string['settings:rag_extract_scorm_desc'] = '解压 SCORM 课件包并索引 <code>imsmanifest.xml</code>、所有 <code>.html</code> 文件以及 Articulate Storyline 的内容字符串。<strong>默认关闭</strong>，因为解析 SCORM 的开销可能较大。课件包大小上限由 <code>rag_scorm_max_mb</code> 控制。';
$string['settings:rag_scorm_max_mb'] = '可索引的 SCORM 课件包大小上限（MB）';
$string['settings:rag_scorm_max_mb_desc'] = '跳过超过此大小的 SCORM 课件包，以免占用过多内存。';
$string['settings:rag_fetch_transcripts'] = '抓取嵌入视频和互动内容的文字稿';
$string['settings:rag_fetch_transcripts_desc'] = '扫描 mod_page 和 mod_book 的内容，查找嵌入的 iframe（Synthesia、YouTube、Articulate、Genially），并抓取与每个嵌入内容配对的文字稿 URL（会在 iframe 的上方和下方同时查找）。需要本服务器能够通过 HTTPS 出站访问文字稿所在主机。<strong>默认关闭</strong>；请在文字稿主机将本服务器加入白名单后（例如 Cloudflare 的 IP 访问规则）再启用。';
$string['settings:rag_iframe_host_patterns'] = 'iframe 主机匹配模式';
$string['settings:rag_iframe_host_patterns_desc'] = '每行一个用于匹配 iframe <code>src</code> 属性的正则表达式。每个匹配到的 iframe 都会被视为互动嵌入内容，其文字稿应被配对并索引。以 <code>#</code> 开头的行为注释。';
$string['settings:rag_transcript_url_pattern'] = '文字稿 URL 匹配模式';
$string['settings:rag_transcript_url_pattern_desc'] = '用于匹配文字稿链接 URL 的正则表达式。索引器会为每个检测到的 iframe 选择距离最近的匹配链接（上方或下方）并将两者配对。留空可停用文字稿配对。';
$string['settings:performance_heading'] = '性能';
