$string['settings:failover_per_call_enabled'] = '按调用故障转移（v5.5.0）';
$string['settings:failover_per_call_enabled_desc'] = '启用后，每次聊天调用都会用故障转移链装饰器包装主提供方。当单次调用超时或返回 5xx 错误时，[[tutorshort]] 会切换到上方<strong>故障转移链</strong>中的下一条，并对故障提供方开启 15 分钟熔断。每次切换都会生成一条审计记录（<code>failover_fallthrough</code>）；启用后请查看 管理 -> [[tutorshort]] -> 审计日志，确认该链运行正常。默认关闭；请在该链通过验证、且贵机构已确认链上每个提供方均已签署所需的数据处理条款后再启用。';
$string['settings:failover_timeout_chat'] = '按调用故障转移：聊天超时（秒）';
$string['settings:failover_timeout_chat_desc'] = '在切换到下一个提供方之前，等待聊天提供方返回首个令牌的时长。默认 8 秒。数值越低，在提供方响应缓慢时切换越快，但也更容易对临时变慢的请求误判；数值越高，则会让该链在主提供方上停留更久。仅在<strong>按调用故障转移</strong>开启时生效。';
$string['settings:spend_notify_emails'] = '支出告警接收人';
