$string['settings:voice_providers_heading'] = '语音提供方（Realtime、TTS、STT）';
$string['settings:voice_providers_heading_desc'] = '配置一个或多个语音 API 提供方。这些设置独立于上方的聊天提供方和 RAG 嵌入提供方——语音之所以拥有独立的提供方列表，是因为目前只有 OpenAI 和 xAI 提供 WebSocket Realtime、TTS 和 STT 接口。请使用下方的下拉框选择由哪个已注册的提供方负责每项能力。若未定义任何行，则使用旧版单密钥回退方式（上方的 Realtime API 密钥，或主 OpenAI 密钥）。若站点使用 Together AI / Anthropic / DeepSeek / Gemini / Mistral 进行聊天，则必须在此至少配置一行，语音功能才能正常工作。';
