$string['settings:bench_default_samples'] = '每次运行的 prompt 数';
$string['settings:bench_default_samples_desc'] = '从网页入队的基准测试会发送多少个 prompt。每个 prompt 会产生两次真实模型调用——答案和评分——所以这就是成本旋钮。代码中上限为 50，这既是 golden 题集的规模，也是让一次运行不超出提供商速率限制的数值。';
$string['settings:bench_heading'] = '模型基准测试';
$string['settings:bench_heading_desc'] = '一次基准测试运行会回答 50 个 prompt，并由一个评分模型按 rubric 给每个答案打分，然后存储一行结果：rubric 均分、每次调用成本，以及首字节时间。运行从模型注册表页面入队，由 cron 执行。';
$string['settings:bench_judge_model'] = '评分模型';
$string['settings:bench_judge_model_desc'] = '给答案打分的模型。更换它会改变之后所有分数的含义，这也正是每次运行都会记录所用评分模型以及运行时的插件版本的原因。';
$string['settings:bench_judge_provider'] = '评分模型提供商';
$string['settings:bench_judge_provider_desc'] = '给答案打分的模型所用的提供商。请让它留在参赛池之外：模型不能给自己打分。';
$string['settings:bench_min_quality_n'] = '可比性下限（已评分项）';
$string['settings:bench_min_quality_n_desc'] = '一次已存储的运行至少要有多少个已评分项，才仍可与另一次运行比较。低于下限的运行仍会保留并显示，但标注为仅供参考，这样三个 prompt 的 smoke 运行永远不可能压过五十个 prompt 的结果。留为 0 表示使用内置默认值；下限设为 0 会使这道防线失效。';
$string['settings:embed_input_type_asymmetric'] = '非对称 查询/文档（推荐）';
$string['settings:embed_input_type_mode'] = '嵌入输入类型';
$string['settings:embed_input_type_mode_desc'] = '仅适用于 Voyage 嵌入。Voyage 会根据文本是查询还是文档采用不同的投影。“非对称”在检索时发送 input_type=query，在建立索引时发送 input_type=document。这是厂商的本意，也是在本语料上测得最好的设置：在查询一侧使用文档投影会损失 30.8 个百分点的召回率，并且在所有查询长度分段中均落后（2026-08-21，voyage-3.5，贴近生产的评测集）。“共享空间”在两侧都发送 input_type=document；它的检索效果明显更差，存在的唯一理由是作为迁移保险——两侧使用同一种投影时，可以在不重新嵌入语料的情况下更换查询模型。除非正处于迁移过程中，否则请选择非对称。修改此项无需重建索引，只有查询侧的投影会改变。这不是模型的非对称配对（用比查询更大的 Voyage 模型建立索引）——那是另一种技术，在本语料上两次都未能复现收益，并且由查询模型设置控制，而非本设置。';
$string['settings:embed_input_type_shared'] = '共享空间（迁移保险；检索效果更差）';
$string['settings:embed_migration_heading'] = '嵌入模型迁移';
$string['settings:embed_migration_heading_desc'] = '更改嵌入模型或其维度会使已存储的每一个向量失效：检索器拒绝把查询与来自另一个嵌入空间的 chunk 打分，因此课程会检索不到任何内容，而不是检索得很差。这些设置描述的是你要迁移「到」的那个模型。随后在 RAG 索引页面逐门课程重新嵌入，新向量与旧向量并存写入，而上面生效中的设置会继续提供检索，直到你自己去修改它们。';
$string['settings:embed_migration_provider_inherit'] = '使用上面已配置的提供商';
$string['settings:embed_migration_target_apikey'] = '目标提供商 API 密钥';
$string['settings:embed_migration_target_apikey_desc'] = '仅当目标提供商与上面配置的提供商不同时才需要填写。留空表示使用现有的嵌入密钥。';
$string['settings:embed_migration_target_dimensions'] = '目标嵌入维度';
$string['settings:embed_migration_target_dimensions_desc'] = '迁移期间请求的向量维度。0 表示使用该模型的原生维度。Voyage 接受 256、512、1024 和 2048；模型不提供的维度会被从请求中省略而不是发送出去，否则你会不知不觉地拿到原生维度而不是你要求的维度。';
$string['settings:embed_migration_target_model'] = '目标嵌入模型';
$string['settings:embed_migration_target_model_desc'] = '迁移期间用于嵌入的模型名称，例如 <code>voyage-4-large</code>。留空表示未配置迁移，RAG 索引页面也不会提供迁移选项。';
$string['settings:embed_migration_target_provider'] = '目标嵌入提供商';
$string['settings:embed_migration_target_provider_desc'] = '留空表示在上面已配置的提供商内部迁移。';
$string['settings:rerank_min_query_chars'] = '重排序：最小查询长度';
$string['settings:rerank_min_query_chars_desc'] = '对于长度不超过这么多字符的查询，跳过重排序器。短查询本质上是关键词式的，在两三个词上重排序器相比余弦相似度几乎没有提升。在 RAG fixture 集上测得：以 50 设卡时召回率 67.7%，而始终开启为 67.2%，成本约为后者的三分之一。设为 0 表示对每个查询都重排序。被跳过的重排序会在消息日志中记为“[Rerank skipped: short_query]”，方便你确认该开关生效。';
$string['settings:spend_export_key'] = '支出导出密钥';
$string['settings:spend_export_key_desc'] = '用于 <code>/local/ai_course_assistant/spend_export.php</code> 上月度 AI 支出导出端点的 Bearer 密钥，支出仪表板每月拉取一次。留空即关闭该端点——此后它对所有请求返回 404。该密钥只在 <code>Authorization: Bearer</code> 头中被接受，绝不接受放在 URL 里。请生成一个足够长的随机值；持有它的人可以读取全站 AI 支出。每次成功导出都会记入插件审计日志。';
$string['task:migrate_course_embeddings'] = '将一门课程迁移到新的嵌入模型';
$string['task:model_price_drift_check'] = '模型价格漂移检查';
$string['task:run_model_benchmark'] = '对模型做基准测试';

