$string['prompt_playground:intro'] = '组装系统提示词并查看结果。有两种模式：(1) 输入<strong>测试问题</strong>以运行真实的检索器，查看它针对该问题所选中的文本块及相关性得分 —— 这是验证文本块选择的方式；或 (2) 粘贴您自己的段落来模拟检索到的文本块。选择一门课程（以及可选的当前页面课程模块 id），然后进行组装。您会看到所选中的文本块、模型将实际收到的提示词，以及各部分的大小明细。不会向任何 AI 提供商发送任何内容，且组装以您（管理员）的身份进行，因此不会暴露学习者数据。';
