$string['settings:anomaly_digest_floor_usd'] = '异常摘要：触发提醒的最低支出（美元）';
$string['settings:anomaly_digest_floor_usd_desc'] = '当过去 24 小时的花费低于此金额时，无论百分比涨幅多大，都不发送 token 支出提醒。基数很小时的百分比只是噪音：从 1 美元翻倍到 2 美元会突破任何阈值，却毫无意义。请将其设为一个真正值得在半夜叫醒您的每日金额。设为 0 则关闭下限，仅按百分比提醒。如果该时间窗内有任何支出来自费率表中没有条目的模型，则无法计价，提醒仍会照常发送 —— 出现无法识别的模型本身就值得关注。';
$string['settings:prompt_truncated_warning'] = '[[tutorshort]] 不得不从提示词中删减检索到的课程内容以符合字符预算，最近一次发生在 {$a}。模型据以作答的课程材料少于检索器所选中的内容。请调高下方的系统提示词字符预算，或减少检索量。';
$string['settings:radar_batch_enabled'] = '将定时报告提交到批处理层';
$string['settings:radar_batch_enabled_desc'] = '默认关闭。开启后，每份定时报告都会按批处理费率提交，并在提供商处理完成后交付，这可能是 24 小时内的任意时刻；在此之前计划中会显示「已提交」状态。所属提供商没有批处理层的计划仍会同步运行，因此不会有报告因此设置而丢失。关闭此设置后，所有计划会在下次运行时回到同步路径，而仍在处理中的批次依然会被收取并交付。';
$string['settings:radar_batch_heading'] = 'Learning Radar：离线批处理层';
$string['settings:radar_batch_heading_desc'] = '定时的 Learning Radar 报告可以发送到 AI 提供商的离线批处理层，输入和输出 token 的费用均可降低 50%，代价是最长 24 小时的处理时间。只有定时报告符合条件：您在本页面即时运行的 Learning Radar 会把答案流式传输到您的浏览器，始终保持同步，所有面向学习者的功能也是如此。批处理支出会记在带 <code>batch/</code> 前缀的模型名称下，因此 AI 支出仪表板显示的是折后费率而非标价。';
$string['settings:soapbox_deprecated_inuse'] = 'Soapbox 已弃用。它正被 PresenterAI 取代 —— 这是一个独立的 Moodle 活动插件，具备 Soapbox 的全部功能，会出现在活动选择器中，并可让您在 S3 存储桶与 Moodle 自带文件存储之间选择，也可在 Moodle 核心 AI 与直接配置的 Claude、OpenAI 或 Gemini 之间选择。本次发布不会有任何变化：您的作业、录音、转录文本、分数和反馈均不受影响，保留期设置依旧完全照旧生效，每日清理任务也仍在运行。相关代码计划在 v8.0.0 中移除，在 PresenterAI 能够导入现有录音和分数之前，不会有任何版本移除它。数据库表会另行并在更晚的时候删除，因为 Soapbox 不写入成绩册条目，这些表是学习者演示记录的唯一副本。您该怎么做：现在起不要再基于 Soapbox 建设新课程；PresenterAI 发布后与其并行安装，并用它开展新工作；现有的 Soapbox 课程则继续运行，直到导入功能可用。目前还无需告知您的学习者任何事情。';
$string['settings:soapbox_deprecated_off'] = 'Soapbox 已弃用，且本站任何地方都未启用它。请保持关闭。它正被 PresenterAI 取代 —— 这是一个独立的 Moodle 活动插件，功能相同，并可选择存储方式和 AI 提供商。相关代码计划在 v8.0.0 中移除。';
