$string['pricedrift:eol_horizon'] = '停用预警提前期（天）';
$string['pricedrift:eol_horizon_desc'] = '提前多久开始报告已公布的模型停用计划。漂移检查只盯着价格；如果没有这一项，就没有任何机制盯着生命周期，真正的停用会以生产事故而不是预警的形式到来——模型会一直正常工作并持续计费，直到它停止，然后所有调用会同时失败。默认 60 天，因为替换一个生产模型意味着一轮横向评测、一次设置变更和一次部署，不是一个下午就能完成的事。停用日期已经过去的情况，无论此处设为多少都始终会被报告。';
