$string['modelregistry:err_badeoldate'] = '生命周期终止日期必须是以 YYYY-MM-DD 格式书写的真实日历日期，或者留空。';
$string['modelregistry:err_noeolsurface'] = '生命周期终止日期必须注明它是针对哪个 API 接口公布的。针对某一个接口公布的停用并不适用于另一个接口；而没有记录接口的日期，正是一条关于你根本不调用的模型的生命周期通知变成误报故障警报的原因。如果它对所有接口都适用，请填写“any”。';
$string['modelregistry:field_eol_date'] = '生命周期终止日期';
$string['modelregistry:field_eol_date_help'] = '已公布的停用或关停日期，格式为 YYYY-MM-DD。尚未公布生命周期终止时请留空 — 留空表示尚未公布，而不表示安全。该日期按 UTC 的日历日解读，而不是按你本地的时区，这样看到这一行的每个人都会按同一周来安排。';
$string['modelregistry:field_eol_surface'] = '生命周期终止适用于';
$string['modelregistry:field_eol_surface_help'] = '该日期是针对哪个 API 接口公布的：<code>gemini-developer-api</code>、<code>vertex-ai</code>、<code>openai-api</code>、<code>azure-openai</code>、<code>bedrock</code>，或用 <code>any</code> 表示所有接口。只要填写了日期就必须填写它，而且这并非走形式：gemini-2.5-flash 曾被报告将于 2026-10-16 停用，但那是 Vertex AI 的生命周期事件，而不是本站点所调用的 Gemini Developer API。没有接口信息，那个日期就会为一个根本不会消失的模型拉响生产故障警报。请在“价格漂移”下列出本站点实际调用的接口，这样不属于你的那些就只作为参考信息显示。';
