$string['privacy:metadata:bench'] = '提供商基准测试运行：站点管理员生成的模型对比结果。其中唯一的个人数据是发起该次运行的管理员的标识符。这些记录属于站点配置，而非关于学习者的个人数据，因此不会包含在数据导出中，也不会在用户请求删除数据时被移除。';
