$string['privacy:metadata:models'] = '模型注册表条目：站点管理员维护的按模型的价格与能力覆盖设置。其中唯一的个人数据是最后保存该条目的管理员的标识符。这些记录属于站点配置，而非关于学习者的个人数据，因此不会包含在数据导出中，也不会在用户请求删除数据时被移除。';
