$string['selftest:storage_intro'] = '将一个小的测试对象在所配置的存储桶中走一圈：上传、检查大小、下载并逐字节比对、删除，然后再确认它确实已消失。每一步都会单独报告，因为哪一步失败正是诊断结论。这会在所配置的录音前缀下的 __selftest/ 文件夹中执行真实的写入和删除，因此走的是与学习者录音完全相同的路径。';
